  await a.focus()
  await page.keyboard.press('Shift+ArrowRight')
  expect(await titlesIn(page, 'doing')).toEqual(['Alpha'])
  await expect(card(page, 'Alpha')).toBeFocused() // focus follows the card
  await page.keyboard.press('Shift+ArrowRight')
